    return <AudioBubble message={message} isMine={isMine} />;
  }

  return (
    <View
      style={[
        styles.row,
        isMine ? styles.rowOutgoing : styles.rowIncoming,
      ]}
    >
      <View
        style={[
          styles.bubble,
          isMine ? styles.bubbleOutgoing : styles.bubbleIncoming,
        ]}
      >
        {showSenderName && !isMine && message.senderName ? (
          <Text style={styles.senderName} numberOfLines={1}>
            {message.senderName}
          </Text>
        ) : null}
        <Text style={styles.text}>{message.text ?? ''}</Text>
